<style>
.nt-page .tc-contact-page{--tc-accent:#8a682d;background:linear-gradient(135deg,#f7f4ee,#faf9f6);color:#34322d;padding-bottom:72px;font-family:var(--nt-sans)}
.nt-page .tc-contact-container{width:var(--nt-shell-width);margin-inline:auto}
.nt-page .tc-contact-breadcrumb{padding:24px 0 8px;color:#817c73}
.nt-page .tc-contact-breadcrumb a{color:inherit}
.nt-page .tc-contact-heading{max-width:none;padding:28px 0 36px}
.nt-page .tc-contact-heading>span{color:#8a682d;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.nt-page .tc-contact-heading h1{font:700 clamp(32px,3.5vw,46px)/1.15 var(--nt-serif);color:#34322d;margin:12px 0 18px;letter-spacing:-.025em}
.nt-page .tc-contact-heading p{max-width:740px;color:#706b63;font-size:16px;line-height:1.8}
.nt-page .tc-contact-copy{padding:24px 28px;background:#fff;border:1px solid #e7e1d6;border-radius:12px;color:#706b63;margin-bottom:30px}
.nt-page .tc-contact-copy>:first-child{margin-top:0}.nt-page .tc-contact-copy>:last-child{margin-bottom:0}
.nt-page .tc-contact-layout{grid-template-columns:minmax(0,.85fr) minmax(0,1.35fr);gap:28px}
.nt-page .tc-contact-info{padding:36px;background:linear-gradient(135deg,#343129,#24231e);color:#fff;border:1px solid #343129;border-radius:14px;box-shadow:0 16px 40px #3431290d}
.nt-page .tc-contact-layout h2{font:700 25px/1.3 var(--nt-serif);margin:0 0 12px}
.nt-page .tc-contact-info>p{color:#d3cdc2;font-size:14px;line-height:1.8}
.nt-page .tc-contact-item{padding:24px 0;border-top:1px solid #ffffff24;gap:18px}
.nt-page .tc-contact-item>.tc-contact-icon{width:44px;height:44px;flex-basis:44px;border-radius:10px;background:#ffffff0d;color:#dbae56}
.nt-page .tc-contact-item h3{color:#d3cdc2;font-size:12px;margin-bottom:8px}
.nt-page .tc-contact-item p,.nt-page .tc-contact-item a{color:#fff;font-size:15px;line-height:1.75}
.nt-page .tc-contact-item a:hover,.nt-page .tc-contact-item .tc-contact-directions{color:#e9c886}
.nt-page .tc-contact-form-card{padding:36px;background:#fff;border:1px solid #e7e1d6;border-radius:14px;box-shadow:0 16px 40px #34312908}
.nt-page .tc-contact-form-card>p{color:#817c73;font-size:14px}
.nt-page .tc-contact-fields{gap:20px 18px}
.nt-page .tc-contact-fields label{font-size:13px;color:#34322d}
.nt-page .tc-contact-fields input,.nt-page .tc-contact-fields textarea{border:1px solid #ddd7cd;border-radius:8px;background:#faf9f6;color:#34322d;padding:13px 14px;font:14px/1.6 var(--nt-sans)}
.nt-page .tc-contact-fields textarea{min-height:160px}
.nt-page .tc-contact-fields input:focus,.nt-page .tc-contact-fields textarea:focus{outline:2px solid #dbae5660;outline-offset:1px;border-color:#8a682d;background:#fff}
.nt-page .tc-contact-fields [aria-invalid=true]{border-color:#c43939}
.nt-page .tc-contact-fields small{color:#817c73}
.nt-page .tc-contact-form-card button{min-height:48px;border-radius:8px;background:#8a682d;color:#fff;font:700 14px var(--nt-sans);padding:14px 26px;margin-top:24px}
.nt-page .tc-contact-form-card button:hover{background:#715323}
.nt-page .tc-contact-page a:focus-visible,.nt-page .tc-contact-page button:focus-visible{outline:3px solid #dbae56;outline-offset:3px}
@media(max-width:800px){.nt-page .tc-contact-layout{grid-template-columns:1fr;gap:24px}.nt-page .tc-contact-info,.nt-page .tc-contact-form-card{padding:28px}}
@media(max-width:480px){.nt-page .tc-contact-page{padding-bottom:40px}.nt-page .tc-contact-heading{padding:22px 0 28px}.nt-page .tc-contact-heading h1{font-size:32px}.nt-page .tc-contact-info,.nt-page .tc-contact-form-card{padding:24px}.nt-page .tc-contact-fields{grid-template-columns:1fr;gap:18px}.nt-page .tc-contact-form-card button{width:100%}}
</style>
